CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE rol (nombre varchar(40) PRIMARY KEY);
CREATE TABLE privilegio (nombre varchar(50) PRIMARY KEY);
CREATE TABLE rol_privilegio (rol varchar(40) REFERENCES rol(nombre), privilegio varchar(50) REFERENCES privilegio(nombre), PRIMARY KEY(rol,privilegio));
CREATE TABLE usuario (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario varchar(80) UNIQUE NOT NULL, contrasena varchar(100) NOT NULL, rol varchar(40) REFERENCES rol(nombre) NOT NULL);
CREATE TABLE punto_acopio (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, razon_social varchar(180) NOT NULL, direccion varchar(250) NOT NULL, zona varchar(80) NOT NULL, material_habitual varchar(80) NOT NULL);
CREATE TABLE ruta (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha date NOT NULL, cerrada boolean NOT NULL DEFAULT false);
CREATE TABLE ruta_usuario (ruta_id bigint REFERENCES ruta(id), usuario_id bigint REFERENCES usuario(id), PRIMARY KEY(ruta_id,usuario_id));
CREATE TABLE ruta_punto (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ruta_id bigint REFERENCES ruta(id) NOT NULL, punto_id bigint REFERENCES punto_acopio(id) NOT NULL, secuencia integer NOT NULL, motivo_omision varchar(500), UNIQUE(ruta_id,punto_id), UNIQUE(ruta_id,secuencia));
CREATE TABLE pesaje (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ruta_id bigint REFERENCES ruta(id) NOT NULL, punto_id bigint REFERENCES punto_acopio(id) NOT NULL, fecha_hora timestamptz NOT NULL, material varchar(80) NOT NULL, peso_bruto double precision NOT NULL, tara double precision NOT NULL, peso_neto double precision NOT NULL CHECK(peso_neto>0), operario_id bigint REFERENCES usuario(id) NOT NULL, observacion varchar(500) NOT NULL DEFAULT '', anulado boolean NOT NULL DEFAULT false, motivo_anulacion varchar(500), anulado_por bigint REFERENCES usuario(id), anulado_en timestamptz, clave_cliente varchar(100) UNIQUE, CHECK(tara>=0 AND peso_bruto>tara));
CREATE INDEX pesaje_punto_idx ON pesaje(punto_id,fecha_hora);
INSERT INTO rol VALUES ('OPERARIO'),('SUPERVISOR'),('ADMINISTRADOR');
INSERT INTO privilegio VALUES ('PUNTO_LEER'),('PESAJE_LEER'),('PESAJE_CREAR'),('PESAJE_EDITAR'),('PESAJE_ANULAR'),('RUTA_CERRAR'),('PUNTO_GESTIONAR');
INSERT INTO rol_privilegio SELECT 'SUPERVISOR',nombre FROM privilegio WHERE nombre<>'PUNTO_GESTIONAR';
INSERT INTO rol_privilegio SELECT 'OPERARIO',nombre FROM privilegio WHERE nombre IN ('PUNTO_LEER','PESAJE_LEER','PESAJE_CREAR','PESAJE_EDITAR');
INSERT INTO rol_privilegio SELECT 'ADMINISTRADOR',nombre FROM privilegio WHERE nombre IN ('PUNTO_LEER','PESAJE_LEER','PUNTO_GESTIONAR');
INSERT INTO usuario(usuario,contrasena,rol) VALUES ('operario1',crypt('Eco2026*',gen_salt('bf',10)),'OPERARIO'),('supervisor1',crypt('Eco2026*',gen_salt('bf',10)),'SUPERVISOR'),('admin',crypt('Eco2026*',gen_salt('bf',10)),'ADMINISTRADOR');
INSERT INTO punto_acopio(razon_social,direccion,zona,material_habitual) SELECT 'Empresa Verde '||i, 'Av. Reciclaje '||(100+i), (ARRAY['Norte','Centro','Sur'])[1+((i-1)%3)], (ARRAY['PAPEL','PLASTICO','VIDRIO'])[1+((i-1)%3)] FROM generate_series(1,12) i;
INSERT INTO ruta(fecha,cerrada) VALUES ((now() AT TIME ZONE 'America/Lima')::date,false),((now() AT TIME ZONE 'America/Lima')::date-1,true);
INSERT INTO ruta_usuario SELECT r.id,u.id FROM ruta r CROSS JOIN usuario u;
INSERT INTO ruta_punto(ruta_id,punto_id,secuencia) SELECT 1,i,i FROM generate_series(1,6)i;
INSERT INTO ruta_punto(ruta_id,punto_id,secuencia) SELECT 2,i,i-6 FROM generate_series(7,12)i;
INSERT INTO pesaje(ruta_id,punto_id,fecha_hora,material,peso_bruto,tara,peso_neto,operario_id,anulado,motivo_anulacion)
SELECT CASE WHEN i<=10 THEN 2 ELSE 1 END, CASE WHEN i<=10 THEN 7+((i-1)%6) ELSE 1+((i-11)%3) END, now()-CASE WHEN i<=10 THEN interval '1 day' ELSE interval '0 day' END,'PAPEL',20+i,2,18+i,CASE WHEN i=15 THEN 2 ELSE 1 END,i=1,CASE WHEN i=1 THEN 'Error de balanza' ELSE null END FROM generate_series(1,15)i;
